//! xoshiro256++ / SplitMix64 against published reference outputs, and the
//! distributions built on them.

use ferric_md::rng::splitmix64;
use ferric_md::Xoshiro256pp;

/// Reference: rand_xoshiro's `Xoshiro256PlusPlus` test vector from state
/// [1, 2, 3, 4] (generated by Vigna's C reference implementation).
#[test]
fn xoshiro256pp_matches_reference_vector() {
    let mut rng = Xoshiro256pp::from_state([1, 2, 3, 4]);
    let expected: [u64; 10] = [
        41943041,
        58720359,
        3588806011781223,
        3591011842654386,
        9228616714210784205,
        9973669472204895162,
        14011001112246962877,
        12406186145184390807,
        15849039046786891736,
        10450023813501588000,
    ];
    for e in expected {
        assert_eq!(rng.next_u64(), e);
    }
}

/// Reference: SplitMix64 outputs for seed 1234567 (Vigna's splitmix64.c,
/// as tabulated in rand_xoshiro's tests).
#[test]
fn splitmix64_matches_reference_vector() {
    let mut s = 1234567u64;
    let expected: [u64; 5] = [
        6457827717110365317,
        3203168211198807973,
        9817491932198370423,
        4593380528125082431,
        16408922859458223821,
    ];
    for e in expected {
        assert_eq!(splitmix64(&mut s), e);
    }
}

#[test]
fn seeding_expands_the_seed_with_splitmix64() {
    let mut s = 0u64;
    let state = [0; 4].map(|_| splitmix64(&mut s));
    let mut a = Xoshiro256pp::seed_from_u64(0);
    let mut b = Xoshiro256pp::from_state(state);
    for _ in 0..8 {
        assert_eq!(a.next_u64(), b.next_u64());
    }
    // Independent check (Python reference implementation of both steps).
    assert_eq!(
        Xoshiro256pp::seed_from_u64(0).next_u64(),
        5987356902031041503
    );
}

#[test]
fn next_f64_uses_the_top_53_bits() {
    let mut a = Xoshiro256pp::seed_from_u64(9);
    let mut b = a.clone();
    for _ in 0..100 {
        let u = a.next_f64();
        let bits = b.next_u64() >> 11;
        assert_eq!(u, bits as f64 / (1u64 << 53) as f64);
        assert!((0.0..1.0).contains(&u));
    }
}

#[test]
fn gaussian_has_unit_normal_moments() {
    let mut rng = Xoshiro256pp::seed_from_u64(2024);
    let n = 200_000;
    let xs: Vec<f64> = (0..n).map(|_| rng.next_gaussian()).collect();
    let mean = xs.iter().sum::<f64>() / n as f64;
    let var = xs.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / n as f64;
    let kurt = xs.iter().map(|x| (x - mean).powi(4)).sum::<f64>() / n as f64 / (var * var);
    eprintln!("gaussian mean {mean:e} var {var} kurtosis {kurt}");
    // Standard errors: mean 2.2e-3, var 3.2e-3, kurtosis 1.1e-2.
    assert!(mean.abs() < 0.01, "mean {mean}");
    assert!((var - 1.0).abs() < 0.015, "var {var}");
    assert!((kurt - 3.0).abs() < 0.06, "kurtosis {kurt}");
    assert!(xs.iter().all(|x| x.is_finite()));
}
